using System.Data;
using System.Text;
using System.Text.Json;
using DbPilot.Models;
using DbPilot.Providers;
using DbPilot.Services;
using DbPilot.ViewModels;

namespace DbPilot.Checks;
internal static class PostgreSqlLiveChecks
{
    public static async Task<int> Run()
    {
        var profile=new ConnectionProfile{Kind=DatabaseKind.PostgreSQL,Host=Environment.GetEnvironmentVariable("DBPILOT_PG_HOST")??throw new Exception("Set DBPILOT_PG_HOST"),Port=int.Parse(Environment.GetEnvironmentVariable("DBPILOT_PG_PORT")??"5432"),Username=Environment.GetEnvironmentVariable("DBPILOT_PG_USER")??"postgres",Password=Environment.GetEnvironmentVariable("DBPILOT_PG_PASSWORD")??throw new Exception("Set DBPILOT_PG_PASSWORD"),Database="postgres",Ssl=Environment.GetEnvironmentVariable("DBPILOT_PG_SSL")=="true",UsePooling=false,Timeout=8};
        string suffix=DateTime.UtcNow.ToString("yyyyMMddHHmmss")+"_"+Guid.NewGuid().ToString("N")[..8],database="dbpilot_test_"+suffix,restored="dbpilot_restore_"+suffix;
        var owned=new HashSet<string>();var results=new List<object>();int passed=0,failures=0;string version="unknown";var started=DateTimeOffset.UtcNow;
        using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(15));var ct=timeout.Token;
        void Check(bool value,string message){if(!value)throw new Exception(message);}
        async Task Test(string name,Func<Task> action){try{await action();passed++;Console.WriteLine("PASS "+name);results.Add(new{name,status="passed"});}catch(Exception ex){failures++;Console.WriteLine("FAIL "+name+": "+ex.Message);results.Add(new{name,status="failed",error=ex.Message});}}
        await using var admin=DbProviderFactory.Create(profile);
        try{
            await admin.TestAsync(ct);version=(await admin.QueryAsync("SELECT version()",1,ct)).Rows[0][0]?.ToString()??"unknown";Console.WriteLine("SERVER "+version);
            await Test("Authentication, database listing and Unicode",async()=>{Check((await admin.DatabasesAsync(ct)).Count>0,"database list");Check((await admin.QueryAsync("SELECT '中文🚀'",1,ct)).Rows[0][0]?.ToString()=="中文🚀","Unicode");});
            await Test("TLS server configuration and certificate-verified connection",async()=>{
                var config=await admin.QueryAsync("SHOW ssl",1,ct);Check(config.Rows[0][0]?.ToString()=="on","Server ssl is off; certificate-verified TLS cannot be tested");
                var secure=MainViewModel.CloneForDatabase(profile,null);secure.Ssl=true;await using var tls=DbProviderFactory.Create(secure);await tls.TestAsync(ct);
                Check((await tls.QueryAsync("SELECT ssl FROM pg_stat_ssl WHERE pid=pg_backend_pid()",1,ct)).Rows[0][0] is true,"connection is not encrypted");
            });
            foreach(var name in new[]{database,restored}){await admin.QueryAsync("CREATE DATABASE "+admin.Quote(name),1,ct);owned.Add(name);}
            var testProfile=MainViewModel.CloneForDatabase(profile,database);await using var db=DbProviderFactory.Create(testProfile);
            var parent=new DbObject(database,"public","parents","表");var items=new DbObject(database,"public","items","表");string Q(DbObject t)=>db.Qualified(t);
            await db.QueryAsync($"CREATE TABLE {Q(parent)} (id integer PRIMARY KEY); INSERT INTO {Q(parent)} VALUES (1); CREATE TABLE {Q(items)} (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, parent_id integer REFERENCES {Q(parent)}(id) ON DELETE SET NULL ON UPDATE CASCADE, name text NOT NULL, qty integer NOT NULL DEFAULT 7, amount numeric(12,3), flag boolean, payload bytea, doc jsonb, happened timestamp(6) without time zone, doubled integer GENERATED ALWAYS AS (qty*2) STORED); CREATE INDEX idx_name ON {Q(items)}(name)",1,ct);
            var fields=await db.ColumnsAsync(items,ct);
            Dictionary<string,object?> Snapshot(QueryResult r)=>r.Columns.Select((n,i)=>(n,r.Rows[0][i])).ToDictionary(p=>p.n,p=>p.Item2);
            await Test("Metadata, view, identity, generated expression, index and foreign key",async()=>{
                await db.QueryAsync($"CREATE VIEW public.item_view AS SELECT id,name FROM {Q(items)}",1,ct);
                Check((await db.ObjectsAsync(database,ct)).Any(o=>o.Name=="item_view"&&o.Kind=="视图"),"view");Check(fields.Single(c=>c.Name=="id").IsIdentity&&fields.Single(c=>c.Name=="doubled").GenerationExpression.Length>0,"generated");
                Check((await db.IndexesAsync(items,ct)).Any(i=>i.Kind=="主键"),"primary key");Check((await db.ForeignKeysAsync(database,ct)).Any(f=>f.OnDelete=="SET NULL"&&f.OnUpdate=="CASCADE"),"foreign key");Check((await db.DefinitionAsync(items,ct)).Contains("CREATE TABLE"),"table definition");
            });
            await Test("Parameterized typed inserts and server defaults",async()=>{
                var changes=new[]{new RowChange(RowChangeKind.Insert,new Dictionary<string,object?>(),new Dictionary<string,object?>{{"name","中文🚀 O'Reilly"},{"parent_id",1},{"qty",9},{"amount",12.375m},{"flag",true},{"payload",new byte[]{0,255}},{"doc","{\"k\":\"中文\"}"},{"happened",new DateTime(2026,10,18,12,0,0).AddTicks(1234560)}}),new RowChange(RowChangeKind.Insert,new Dictionary<string,object?>(),new Dictionary<string,object?>{{"name","defaults"}})};
                Check(await ((IEditableDbProvider)db).ApplyChangesAsync(items,changes,ct)==2,"insert");var r=await db.QueryAsync($"SELECT * FROM {Q(items)} ORDER BY id",10,ct);Check(r.Rows.Count==2&&Convert.ToInt32(r.Rows[0][r.Columns.ToList().IndexOf("doubled")])==18&&Convert.ToInt32(r.Rows[1][3])==7,"defaults/generated");
            });
            await Test("Update, NULL, stale snapshot conflict and transactional rollback",async()=>{
                var original=Snapshot(await db.QueryAsync($"SELECT * FROM {Q(items)} ORDER BY id",1,ct));var edit=(IEditableDbProvider)db;
                await edit.ApplyChangesAsync(items,[new(RowChangeKind.Update,original,new Dictionary<string,object?>{{"name","updated"},{"payload",null}})],ct);
                bool conflict=false;try{await edit.ApplyChangesAsync(items,[new(RowChangeKind.Delete,original,new Dictionary<string,object?>())],ct);}catch(DBConcurrencyException){conflict=true;}Check(conflict,"stale delete");
                bool failed=false;try{await edit.ApplyChangesAsync(items,[new(RowChangeKind.Insert,new Dictionary<string,object?>(),new Dictionary<string,object?>{{"name","rollback"}}),new(RowChangeKind.Insert,new Dictionary<string,object?>(),new Dictionary<string,object?>{{"name","bad"},{"parent_id",999}})],ct);}catch{failed=true;}Check(failed&&Convert.ToInt32((await db.QueryAsync($"SELECT COUNT(*) FROM {Q(items)} WHERE name='rollback'",1,ct)).Rows[0][0])==0,"rollback");
            });
            await Test("CSV import, all export formats and typed migration",async()=>{
                var source=new DbObject(database,"public","transfer_source","表");var target=source with{Name="transfer_target"};
                foreach(var table in new[]{source,target})await db.QueryAsync($"CREATE TABLE {Q(table)} (id integer PRIMARY KEY,label text,flag boolean,amount numeric(12,3),payload bytea)",1,ct);
                var columns=await db.ColumnsAsync(source,ct);Check(await db.InsertRowsAsync(source,columns.Select(c=>c.Name).ToArray(),CsvData.MapAsync(new StringReader("id,label,flag,amount,payload\n1,中文,true,12.375,AP8=\n2,\\N,false,-1.250,"),true,[0,1,2,3,4],columns,DatabaseKind.PostgreSQL,ct),null,ct)==2,"CSV");
                foreach(var format in new[]{"csv","json","sql"}){await using var output=new MemoryStream();Check(await DataTransfer.ExportAsync(db,testProfile,source,output,format,null,ct)==2&&output.Length>0,"export "+format);}
                await using var other=DbProviderFactory.Create(testProfile);Check(await DataTransfer.MigrateAsync(db,testProfile,source,other,testProfile,target,null,ct)==2,"migration");
            });
            await Test("Paging, multiple results, streaming and EXPLAIN",async()=>{
                Check((await db.QueryAsync(db.PageSql(items,"",1,1),1,ct)).Rows.Count==1,"page");var results=await db.QueryMultipleAsync($"SELECT * FROM {Q(items)}; SELECT 42",1,ct);Check(results.Count==2&&results[0].Truncated&&Convert.ToInt32(results[1].Rows[0][0])==42,"multiple");int count=0;await foreach(var batch in db.StreamAsync($"SELECT * FROM {Q(items)}",1,ct))count+=batch.Rows.Count;Check(count==2,"stream");Check((await db.ExplainAsync($"SELECT * FROM {Q(items)}",ct)).Count>0,"explain");
            });
            await Test("Dollar-quoted overloads, procedure, sequence and definitions",async()=>{
                string sql="CREATE FUNCTION public.test_fn(x integer) RETURNS integer LANGUAGE plpgsql AS $$ BEGIN RETURN x+1; END; $$; CREATE FUNCTION public.test_fn(x text) RETURNS text LANGUAGE sql AS $$ SELECT x || '!'; $$; CREATE PROCEDURE public.test_proc() LANGUAGE plpgsql AS $$ BEGIN PERFORM 1; END; $$; CREATE SEQUENCE public.test_seq; CALL public.test_proc(); SELECT public.test_fn(10);";
                var outcomes=await ScriptRunner.RunAsync(db,new StringReader(sql),DatabaseKind.PostgreSQL,false,20,null,ct);Check(outcomes.All(o=>o.Error is null),string.Join("; ",outcomes.Select(o=>o.Error)));Check(Convert.ToInt32(outcomes.Last().Results.Last().Rows[0][0])==11,"function");
                var objects=await db.ObjectsAsync(database,ct);Check(objects.Count(o=>o.Name=="test_fn")==2,"overloads");foreach(var obj in objects.Where(o=>o.Name is "test_fn" or "test_proc" or "test_seq"))Check((await db.DefinitionAsync(obj,ct)).Length>0,"definition "+obj.Name);
            });
            await Test("Trigger transformation, audit writes, rejection and rollback",async()=>{
                const string script="CREATE TABLE public.trigger_target(id integer PRIMARY KEY,value integer NOT NULL); CREATE TABLE public.trigger_audit(id integer,value integer); CREATE FUNCTION public.trigger_action() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.value<0 THEN RAISE EXCEPTION 'negative value rejected'; END IF; NEW.value=NEW.value+10; INSERT INTO public.trigger_audit VALUES(NEW.id,NEW.value); RETURN NEW; END; $$; CREATE TRIGGER before_write BEFORE INSERT OR UPDATE ON public.trigger_target FOR EACH ROW EXECUTE FUNCTION public.trigger_action();";
                var outcomes=await ScriptRunner.RunAsync(db,new StringReader(script),DatabaseKind.PostgreSQL,false,20,null,ct);Check(outcomes.All(o=>o.Error is null),string.Join("; ",outcomes.Select(o=>o.Error)));
                var table=new DbObject(database,"public","trigger_target","表");var edit=(IEditableDbProvider)db;
                RowChange Insert(int id,int value)=>new(RowChangeKind.Insert,new Dictionary<string,object?>(),new Dictionary<string,object?>{{"id",id},{"value",value}});
                await edit.ApplyChangesAsync(table,[Insert(1,5)],ct);var r=await db.QueryAsync("SELECT * FROM public.trigger_target",1,ct);Check(Convert.ToInt32(r.Rows[0][1])==15,"trigger transformation");
                await edit.ApplyChangesAsync(table,[new(RowChangeKind.Update,Snapshot(r),new Dictionary<string,object?>{{"value",20}})],ct);Check(Convert.ToInt32((await db.QueryAsync("SELECT value FROM public.trigger_target",1,ct)).Rows[0][0])==30,"trigger update");
                bool rejected=false;try{await edit.ApplyChangesAsync(table,[Insert(2,5),Insert(3,-1)],ct);}catch{rejected=true;}
                Check(rejected&&Convert.ToInt32((await db.QueryAsync("SELECT COUNT(*) FROM public.trigger_target",1,ct)).Rows[0][0])==1&&Convert.ToInt32((await db.QueryAsync("SELECT COUNT(*) FROM public.trigger_audit",1,ct)).Rows[0][0])==2,"trigger batch and audit rollback");
            });
            await Test("100000-row import, streaming, export, migration and late rollback",async()=>{
                var source=new DbObject(database,"public","large_source","表");var target=source with{Name="large_target"};
                foreach(var table in new[]{source,target})await db.QueryAsync($"CREATE TABLE {Q(table)}(id integer PRIMARY KEY,label text,amount numeric(12,3))",1,ct);
                async IAsyncEnumerable<object?[]> Rows(int count,bool duplicate=false){for(int i=1;i<=count;i++){yield return [duplicate&&i==count?1:i,"中文🚀 row "+i,i*0.125m];if(i%1000==0)await Task.Yield();}}
                var timer=System.Diagnostics.Stopwatch.StartNew();Check(await db.InsertRowsAsync(source,["id","label","amount"],Rows(100000),null,ct)==100000,"large import");var insertMs=timer.ElapsedMilliseconds;
                int count=0;long sum=0;await foreach(var batch in db.StreamAsync($"SELECT * FROM {Q(source)}",500,ct)){count+=batch.Rows.Count;sum+=batch.Rows.Sum(r=>Convert.ToInt64(r[0]));}Check(count==100000&&sum==5000050000L,"stream completeness");var streamMs=timer.ElapsedMilliseconds-insertMs;
                long bytes=0;foreach(var format in new[]{"csv","json","sql"}){await using var output=new MemoryStream();Check(await DataTransfer.ExportAsync(db,testProfile,source,output,format,null,ct)==100000,"export "+format);bytes+=output.Length;}
                var exportEnd=timer.ElapsedMilliseconds;
                await using var other=DbProviderFactory.Create(testProfile);Check(await DataTransfer.MigrateAsync(db,testProfile,source,other,testProfile,target,null,ct)==100000,"large migration");
                Check(Convert.ToInt64((await other.QueryAsync($"SELECT SUM(id) FROM {Q(target)}",1,ct)).Rows[0][0])==5000050000L,"migrated checksum");var migrateEnd=timer.ElapsedMilliseconds;
                await other.QueryAsync($"TRUNCATE {Q(target)}",1,ct);bool failed=false;try{await other.InsertRowsAsync(target,["id","label","amount"],Rows(10000,true),null,ct);}catch{failed=true;}
                Check(failed&&Convert.ToInt32((await other.QueryAsync($"SELECT COUNT(*) FROM {Q(target)}",1,ct)).Rows[0][0])==0,"10000th-row failure rollback");
                var metric=new{name="100000-row measurements",insertMs,streamMs,exportMs=exportEnd-insertMs-streamMs,migrationMs=migrateEnd-exportEnd,exportBytes=bytes,totalMs=timer.ElapsedMilliseconds};results.Add(metric);Console.WriteLine("METRIC "+JsonSerializer.Serialize(metric));
            });
            await Test("Logical backup/restore and generated identity continuity",async()=>{
                await using var output=new MemoryStream();await DataTransfer.BackupAsync(db,testProfile,[parent,items],output,null,ct);
                await using var restore=DbProviderFactory.Create(MainViewModel.CloneForDatabase(profile,restored));var outcomes=await ScriptRunner.RunAsync(restore,new StringReader(Encoding.UTF8.GetString(output.ToArray())),DatabaseKind.PostgreSQL,false,20,null,ct);Check(outcomes.All(o=>o.Error is null),string.Join("; ",outcomes.Select(o=>o.Error)));
                Check(Convert.ToInt32((await restore.QueryAsync("SELECT COUNT(*) FROM public.items",1,ct)).Rows[0][0])==2,"restore rows");await restore.QueryAsync("INSERT INTO public.items(name) VALUES ('after restore')",1,ct);Check(Convert.ToInt32((await restore.QueryAsync("SELECT COUNT(*) FROM public.items",1,ct)).Rows[0][0])==3,"identity continuation");
            });
            await Test("Cancel and reuse original connection",async()=>{using var cancel=new CancellationTokenSource(500);bool cancelled=false;try{await db.QueryAsync("SELECT pg_sleep(10)",1,cancel.Token);}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&Convert.ToInt32((await db.QueryAsync("SELECT 1",1,ct)).Rows[0][0])==1,"cancel/recovery");});
        }catch(Exception ex){failures++;Console.WriteLine("FATAL "+ex.Message);results.Add(new{name="setup",status="failed",error=ex.Message});}
        finally{
            foreach(var name in owned)try{if(name!=database&&name!=restored)throw new Exception("cleanup rejected");await using var cleanup=DbProviderFactory.Create(profile);await cleanup.QueryAsync("DROP DATABASE "+cleanup.Quote(name),1,CancellationToken.None);Console.WriteLine("CLEANUP "+name);results.Add(new{name="cleanup "+name,status="passed"});}catch(Exception ex){failures++;results.Add(new{name="cleanup "+name,status="failed",error=ex.Message});Console.WriteLine("CLEANUP FAILED "+ex.Message);}
            Directory.CreateDirectory("artifacts");await File.WriteAllTextAsync("artifacts/pgsql-live-report.json",JsonSerializer.Serialize(new{host=profile.Host,port=profile.Port,version,started,finished=DateTimeOffset.UtcNow,passed,failures,results},new JsonSerializerOptions{WriteIndented=true}));
        }
        Console.WriteLine($"LIVE PGSQL: {passed} passed, {failures} failed.");return failures==0?0:1;
    }
}
